import{_ as t,c as n,o as a,ag as s}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Deploy, Start, and Channel State","description":"What deploying a channel actually does, what each state means, what Start, Stop, Pause, and Halt do to connectors and queues, and which saved changes need a redeploy","frontmatter":{"title":"Deploy, Start, and Channel State","description":"What deploying a channel actually does, what each state means, what Start, Stop, Pause, and Halt do to connectors and queues, and which saved changes need a redeploy"},"headers":[],"relativePath":"engine/channel_state.md","filePath":"engine/channel_state.md","lastUpdated":1793057853000}'),o={name:"engine/channel_state.md"};function d(r,e,i,h,l,c){return a(),n("div",null,e[0]||(e[0]=[s('<h1 id="deploy-start-and-channel-state" tabindex="-1">Deploy, Start, and Channel State <a class="header-anchor" href="#deploy-start-and-channel-state" aria-label="Permalink to &quot;Deploy, Start, and Channel State&quot;">​</a></h1><p>Saving a channel stores its definition. Deploying it loads that definition into the engine: scripts are compiled, connectors are created and told they are deployed, the channel&#39;s database tables are reconciled, and the channel is started, paused, or left stopped according to its Initial State. Until a channel is deployed, the engine has not loaded it. After it is deployed, the engine runs what it loaded and does not re-read the saved definition until the next deploy, so a saved change to a connector, a transformer, a storage setting, or a code template does not reach the running channel.</p><h2 id="what-deploy-does" tabindex="-1">What deploy does <a class="header-anchor" href="#what-deploy-does" aria-label="Permalink to &quot;What deploy does&quot;">​</a></h2><p>When one or more channels are deployed, the engine proceeds in this order.</p><ol><li>Any channel in the set that is already deployed is undeployed first, and the global undeploy script then runs once. A redeploy is an undeploy followed by a deploy.</li><li>The global deploy script runs once, before any channel.</li><li>Channels with dependencies are ordered so that a channel deploys before the channels that depend on it; channels without dependencies deploy in parallel.</li></ol><p>For each channel:</p><ol start="4"><li>The channel is skipped, without error, if it is disabled.</li><li>The engine builds the channel from the saved definition, creating its connectors. Filters, transformers, and response transformers are compiled at this point.</li><li>The four channel scripts are compiled.</li><li>The global channel map is cleared, if the channel&#39;s setting asks for it.</li><li>The deploy script runs. If it throws, the deploy fails and the channel is not deployed.</li><li>The storage mode is checked against the queue settings; a channel whose mode cannot support its queues fails to deploy.</li><li>The custom metadata columns are reconciled with the channel&#39;s definition, the queues are attached to their database queries, and every connector is told it is deployed.</li><li><strong>Initial State</strong> decides what happens next. Started: the channel is started. Paused: everything starts except the source connector. Stopped: nothing starts and the channel stays deployed but stopped.</li></ol><p>Message recovery, which picks up messages that were mid-flight when the engine last stopped, happens during start, not deploy. A channel deployed with Initial State Stopped recovers nothing until it is started.</p><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><p>A channel rests in one of these states.</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Undeployed</strong></td><td>Saved, but not loaded in the engine</td></tr><tr><td><strong>Started</strong></td><td>The source connector is accepting input and every part of the channel is running</td></tr><tr><td><strong>Paused</strong></td><td>The source connector is stopped. Everything else, including the queues, is running</td></tr><tr><td><strong>Stopped</strong></td><td>Deployed but nothing is running. Queued messages wait in the database</td></tr></tbody></table><p>The Dashboard shows the channel&#39;s state and, for each connector, whether it is running. While a task is in progress it can also show Deploying, Undeploying, Starting, Stopping, or Pausing.</p><h2 id="start-stop-pause-resume-halt" tabindex="-1">Start, Stop, Pause, Resume, Halt <a class="header-anchor" href="#start-stop-pause-resume-halt" aria-label="Permalink to &quot;Start, Stop, Pause, Resume, Halt&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Start</strong></td><td>Starts the destination connectors, runs message recovery, starts the destination queues, starts the source queue, and starts the source connector last. Allowed from Stopped, or directly after deploy</td></tr><tr><td><strong>Stop</strong></td><td>Stops the source connector, then waits for every message currently in flight to finish, then stops the destination connectors and the queue threads. Nothing is abandoned. Queued rows stay in the database and resume on the next start</td></tr><tr><td><strong>Pause</strong></td><td>Stops the source connector and nothing else. In-flight messages finish, the source queue keeps draining, and the destination queues keep sending. Allowed from Started</td></tr><tr><td><strong>Resume</strong></td><td>Starts the source connector again. Allowed from Paused</td></tr><tr><td><strong>Halt</strong></td><td>Interrupts every processing and queue thread without waiting. A message interrupted mid-send may or may not have been delivered, and the engine cannot tell which; the sender gets an error or a dropped connection with no reply, although the message is stored and recovered when the channel starts again, so a duplicate is possible. The Dashboard offers Halt only while a channel, or one of its connectors, is Deploying, Undeploying, Starting, Stopping, Pausing, Syncing, or Unknown</td></tr></tbody></table><h3 id="single-connectors" tabindex="-1">Single connectors <a class="header-anchor" href="#single-connectors" aria-label="Permalink to &quot;Single connectors&quot;">​</a></h3><p>The Dashboard allows a connector to be started or stopped on its own. For the source connector this is the same as resume and pause. A destination can be stopped on its own only if its queueing is enabled, because its messages have to go somewhere: while it is stopped, every message for that destination goes to its queue regardless of the queue mode, and sending resumes when it is started.</p><h2 id="undeploy" tabindex="-1">Undeploy <a class="header-anchor" href="#undeploy" aria-label="Permalink to &quot;Undeploy&quot;">​</a></h2><p>Undeploying a channel stops it first, with the same wait for in-flight messages that Stop performs. The queues are not drained; their rows stay in the database and are picked up when the channel is deployed and started again. The connectors are told they are undeployed, the filter, transformer and response transformer objects are disposed, the undeploy script runs, and only then are the four compiled channel scripts discarded from the cache. A failure in the undeploy script is logged and recorded as an event but does not stop the undeploy.</p><p>When several channels are undeployed together, a channel is undeployed before the channels it depends on, and the global undeploy script runs once at the end.</p><h2 id="what-a-saved-change-needs" tabindex="-1">What a saved change needs <a class="header-anchor" href="#what-a-saved-change-needs" aria-label="Permalink to &quot;What a saved change needs&quot;">​</a></h2><p>A change to a deployed channel takes effect on the next deploy. The table also shows when changes outside the channel take effect.</p><table tabindex="0"><thead><tr><th>Change</th><th>Takes effect</th></tr></thead><tbody><tr><td>Any channel setting: connectors, filters, transformers, scripts, storage, threads, response, dependencies, initial state</td><td>On the next deploy</td></tr><tr><td>A code template used by the channel</td><td>On the next deploy. Code templates are copied into every compiled script at deploy time</td></tr><tr><td>The configuration map</td><td>Immediately. Every script run reads the current map</td></tr><tr><td>The global preprocessor and postprocessor</td><td>Immediately. They are recompiled when saved and looked up on every message</td></tr><tr><td>The global deploy and undeploy scripts</td><td>On the next deploy or undeploy, which is the only time they run</td></tr></tbody></table><p>The Dashboard and the Channels view both carry a <strong>Rev Δ</strong> column: the number of times the channel has been saved since it was deployed, calculated as the saved revision minus the deployed revision. It is highlighted when it is above zero, and also when any code template linked to the channel has changed since the deploy, since that change needs a redeploy too but does not touch the channel&#39;s own revision.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>The <strong>Set Dependencies</strong> button on the Summary tab records that one channel depends on another. The dependencies form a directed graph, and the engine refuses one that contains a cycle.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Order</th></tr></thead><tbody><tr><td>Deploy, Start, Resume</td><td>A channel goes before the channels that depend on it</td></tr><tr><td>Undeploy, Stop, Pause</td><td>A channel goes before the channels it depends on</td></tr></tbody></table><p>Channels at the same level run in parallel, and the engine waits for a whole level before moving to the next. If a channel fails to deploy or start, every channel that depends on it, directly or through another channel, is left out of that operation, and the server log names them.</p><h2 id="server-startup-enabled-and-deployed" tabindex="-1">Server startup, enabled, and deployed <a class="header-anchor" href="#server-startup-enabled-and-deployed" aria-label="Permalink to &quot;Server startup, enabled, and deployed&quot;">​</a></h2><p>On startup, when <code>server.startupdeploy</code> is true, which is the default, the engine deploys every channel it has. Disabled channels are skipped. Each deployed channel then follows its Initial State, so a channel with Initial State Stopped is deployed on startup but not running.</p><p>Enabled and deployed are separate things. Enabled is metadata kept beside the channel rather than part of it; changing it does not change the channel&#39;s revision. A disabled channel is skipped by deploy, and <strong>Deploy Channel</strong> and <strong>Debug Channel</strong> leave it out, except that <strong>Deploy Channel</strong> in the channel editor offers to enable the channel and then deploys it. Disabling a channel that is already deployed does not undeploy it; it keeps running until it is undeployed or the server restarts. <strong>Redeploy All</strong> undeploys everything, clears the global map if the server setting asks for it, and then deploys every enabled channel. The global undeploy script still sees the global map values, and when the map is cleared the global deploy script sees it empty.</p>',30)]))}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
